  "0006_cleanup_profiles_table.sql": "-- Remove Bloom filter columns from profiles table (deprecating migration 0005 approach)\r\n-- SQLite doesn't support DROP COLUMN, so we recreate the table\r\nCREATE TABLE profiles_temp (\r\n    id TEXT PRIMARY KEY,\r\n    owner_id TEXT REFERENCES users(id) ON DELETE CASCADE,\r\n    name TEXT NOT NULL,\r\n    settings TEXT NOT NULL,\r\n    created_at INTEGER NOT NULL,\r\n    updated_at INTEGER NOT NULL,\r\n    last_active_at INTEGER\r\n);\r\n\r\nINSERT INTO profiles_temp SELECT id, owner_id, name, settings, created_at, updated_at, last_active_at FROM profiles;\r\n\r\nDROP TABLE profiles;\r\nALTER TABLE profiles_temp RENAME TO profiles;\r\n\r\nCREATE INDEX IF NOT EXISTS idx_profiles_owner ON profiles(owner_id);\r\n",
  "0007_user_activity_and_totp.sql": "-- 用户安全活动日志\nCREATE TABLE IF NOT EXISTS user_activity_log (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    user_id TEXT NOT NULL,\n    action TEXT NOT NULL CHECK(action IN (\n        'login_success', 'login_fail', 'logout',\n        'password_change_success', 'password_change_fail',\n        'totp_verify_success', 'totp_verify_fail',\n        'totp_setup', 'totp_removed',\n        'recovery_key_used'\n    )),\n    ip_address TEXT,\n    user_agent TEXT,\n    timestamp INTEGER NOT NULL,\n    extra TEXT, -- JSON 附加信息 (如失败原因)\n    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\n-- 待验证的 TOTP 临时会话 (密码验证通过，等待 TOTP 验证)\nCREATE TABLE IF NOT EXISTS pending_totp_sessions (\n    id TEXT PRIMARY KEY,\n    user_id TEXT NOT NULL,\n    expires_at INTEGER NOT NULL,\n    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\n-- TOTP 相关字段\nALTER TABLE users ADD COLUMN totp_secret TEXT;\nALTER TABLE users ADD COLUMN totp_enabled INTEGER DEFAULT 0;\n-- 跳过密码模式：启用后登录只需 TOTP，不需要密码\nALTER TABLE users ADD COLUMN totp_skip_password INTEGER DEFAULT 0;\n-- 恢复密钥：JSON 数组，存储 SHA-256 哈希后的 8 个一次性密钥\nALTER TABLE users ADD COLUMN totp_recovery_keys TEXT;\n\n-- 索引\nCREATE INDEX IF NOT EXISTS idx_activity_log_user ON user_activity_log(user_id, timestamp DESC);\nCREATE INDEX IF NOT EXISTS idx_pending_totp_expires ON pending_totp_sessions(expires_at);\n",
  "0008_add_profile_key.sql": "-- Add profile_key column to profiles table\nALTER TABLE profiles ADD COLUMN profile_key TEXT;\n\n-- Backfill profile_key with existing id for backward compatibility\nUPDATE profiles SET profile_key = LOWER(id) WHERE profile_key IS NULL;\n\n-- Create unique index\nCREATE UNIQUE INDEX IF NOT EXISTS idx_profiles_key ON profiles(profile_key);\n",
